sealed class Outcome320 {
    data class Success(val payload: String) : Outcome320()
    data object Failure : Outcome320()
}

fun describe320(outcome: Outcome320): String = when (outcome) {
    is Outcome320.Success -> outcome.payload
    Outcome320.Failure -> "failed"
}
